import { useState, useEffect } from 'react';

export function useVirtualizer({ count, rowHeight, containerHeight, scrollTop, overscan = 5 }) {
  const startIndex = Math.max(0, Math.floor(scrollTop / rowHeight) - overscan);
  const endIndex = Math.min(count - 1, Math.floor((scrollTop + containerHeight) / rowHeight) + overscan);
  const virtualItems = [];
  for (let i = startIndex; i <= endIndex; i++) {
    virtualItems.push({ index: i, start: i * rowHeight, size: rowHeight });
  }
  return { virtualItems, totalHeight: count * rowHeight };
}

