self.onmessage = (e) => {
  const { data, filterText, sortKey, sortDir } = e.data;
  let filtered = data.filter(item => 
    !filterText || item.patientName.toLowerCase().includes(filterText.toLowerCase())
  );
  if (sortKey) {
    filtered.sort((a, b) => (a[sortKey] > b[sortKey] ? 1 : -1) * (sortDir === 'desc' ? -1 : 1));
  }
  self.postMessage(filtered);
};

