export class MutationQueue {
  private queue = [];
  enqueue(m) { this.queue.push(m); }
  flush(sender) {
    let count = 0;
    while (this.queue.length > 0) {
      const item = this.queue[0];
      if (sender(item)) {
        this.queue.shift();
        count++;
      } else break;
    }
    return count;
  }
}

